int Trace(string text, int value) { Print(text); return value; }
class C {
 public static int A = Trace("static-field", 1);
 public static int B { get; set; } = Trace("static-property", 2);
 public int X = Trace("instance-field", 3);
 static C() { Print("static-body"); }
 public C(int x) { Print("instance-body:" + x); }
 public int Read() { Print("method"); return A + B + X; }
}
class Unused { static Unused() { Print("unexpected"); } }
void Main() {
 Print("start"); var c = new C(Trace("argument", 7)); Print(c.Read());
 var other = new C(8); Print(other.Read());
}
